function absorption(t,s){let o=label(560,150,'One epithelial layer; different destinations','同一層上皮；不同營養素的目的地',23)+label(240,210,'Intestinal lumen','小腸腔',21)+label(535,210,'Epithelium','上皮',21)+label(730,210,'Tissue fluid','組織液',19);
 const rows=[245,325,405,485,565];for(const y of rows){o+=V.enterocyte(460,y,150,76,{brush:false});for(let j=0;j<7;j++)o+=path([[460,y+7+j*9],[443,y+7+j*9]],'#ab7a6f',2)}
 const blood=[[870,100],[870,555],[1140,555]],lymph=[[870,635],[870,735],[1140,735]];o+=cap(blood,'#a86483',42)+path(lymph,'#789650',48)+path(lymph,'#e3edce',38)+label(1010,300,'Blood capillary','微血管',19)+label(1010,657,'Lacteal','乳糜管',19);
 o+=path([[610,573],[610,625]],'#fffdf8',7)+path([[608,573],[625,589],[625,609],[608,625]],'#ab7d70',3);
 const groups=[['glucose',270,'capillary'],['amino',350,'capillary'],['water',430,'capillary'],['#57905f',510,'capillary'],['lipid',590,'lacteal'],['#a19328',614,'lacteal']];
 let bloodOut=0,lymphOut=0;
 for(const [k,[type,y,dest]]of groups.entries()){if(s.absorptionGroup==='water'&&dest!=='capillary'||s.absorptionGroup==='lipid'&&dest!=='lacteal')continue;const yy=k===5?600:y;if(dest==='capillary'){o+=gate(460,yy,true)+gate(610,yy,true)+path([[846,yy-12],[846,yy+12]],'#fffdf8',8)}else o+=path([[846,647],[846,674]],'#fffdf8',8)+path([[846,647],[855,660],[846,674]],'#789650',3);
 for(let i=0;i<6;i++){const q=ramp(t,.025+i*.025,.79+i*.035),route=dest==='capillary'?[[150+i*34,yy+(i%2?10:-10)],[440,yy],[460,yy],[530,yy],[610,yy],[690,yy],[846,yy],[870,yy],[870,555],[1135,555]]:[[150+i*34,yy+(i%2?7:-7)],[443,yy],[460,yy],[530,yy],[590,yy],[610,yy],[730,660],[846,660],[870,660],[870,735],[1135,735]],p=at(route,q),packed=dest==='lacteal'&&p[0]>550;if(q===1){if(dest==='capillary')bloodOut++;else lymphOut++}else{o+=`<g opacity="${Math.min(1,(1-q)*35)}">`+(type==='lipid'?`<g data-absorption-unit="${k}-${i}" data-destination="${dest}">`+(packed?`<g transform="translate(${p[0]} ${p[1]}) scale(.48)">${V.triglyceride(0,0)}</g>`:V.fattyAcid(...p))+'</g>':token(...p,type,`data-absorption-unit="${k}-${i}" data-destination="${dest}"`,8));if(packed)o+=circle(...p,12,'none','stroke="#699047" stroke-width="2"');o+='</g>'}}}
 o+=label(1010,595,`Carried away: ${bloodOut}`,`已帶走：${bloodOut}`,18)+label(535,700,'Long-chain fat: packaged inside cells','長鏈脂肪：在上皮細胞內包裝',18)+label(1010,785,`Into lymph: ${lymphOut}`,`淋巴已帶走：${lymphOut}`,18);return V.wrap(o,'Expanded absorption routes; vessels separated for clarity');}

function overview(t){const stage=Math.min(3,Math.floor(t*4)),regions=[[687,246,285,80],[700,338,245,180],[190,450,45,90],[235,260,130,430]],a=regions[stage];let svg=priorRender('villi',{adaptation:'overview',phase:0});svg=svg.replace(/<g data-overview-(?:atp|glucose)="[^"]*">[\s\S]*?<\/g>/g,'');svg=svg.replace(/<text\b[^>]*y="743"[^>]*>[\s\S]*?<\/text>/g,'');const labels=[['Microvilli → more membrane area','微絨毛 → 增加細胞膜面積'],['Mitochondria → ATP for active uptake','線粒體 → ATP 支持主動吸收'],['One cell thick → shorter diffusion route','單層細胞 → 擴散路徑較短'],['Capillaries + lacteal → carry absorbed food away','微血管及乳糜管 → 帶走已吸收營養素']];return svg.replace('</svg>',`<rect x="${a[0]}" y="${a[1]}" width="${a[2]}" height="${a[3]}" rx="10" fill="none" stroke="#357f73" stroke-width="5"/></svg>`)}
const definitions={
 overview:['Villus + epithelial cell','絨毛及上皮細胞','Locate the adaptation, then use its tab to see the mechanism','先辨認適應結構，再用分頁觀察機制'],
 absorption:['One selective epithelial layer','單層選擇性上皮','Materials cross the lining, then leave in blood or lymph','物質穿過上皮，再由血液或淋巴帶走'],
 long:['Long intestine','小腸長','More wall area and longer contact time','內壁面積較大，接觸時間較長'],
 folds:['Circular folds of the intestinal wall','腸壁的環形摺疊','More lining area within the same intestinal length','相同小腸長度內有更多內壁面積'],
 villi:['Numerous villi on the mucosa','黏膜上的大量絨毛','More epithelial surface for absorption','增加上皮吸收表面積'],
 microvilli:['Many microvilli on ONE cell','同一細胞有大量微絨毛','More membrane area for absorption','增加可供吸收的細胞膜面積'],
 wall:['One-cell-thick epithelium','單層上皮','Shorter diffusion distance to the blood','到達血液的擴散路徑較短'],
 energy:['Many mitochondria','大量線粒體','ATP supply supports active nutrient uptake','ATP 供應支持主動吸收營養素'],
 blood:['Capillary network + blood flow','微血管網及血流','Removal maintains a diffusion concentration gradient','帶走溶質以維持擴散的濃度梯度'],
 lacteal:['Central lacteal','中央乳糜管','Receives and drains packaged long-chain dietary fat','接收及帶走包裝後的長鏈膳食脂肪'],
 mixing:['Peristalsis and movement near villi','蠕動及絨毛附近的運動','Freshly digested contents renew the concentration difference','新消化的食糜更新表面附近的濃度差']
};
const stories={
 overview:[['Find structure 找結構','Find cell 看細胞','Link to benefit 連結作用','See route 看運輸'],['The whole villus and the enlarged cell are linked by dashed lines. The zoom is for structure, not a second layer of cells. 虛線連接整條絨毛及放大細胞；放大並非另一層細胞。','Microvilli are folds of ONE epithelial cell membrane. Mitochondria are inside that cell; capillaries and the lacteal are inside the villus, not inside microvilli. 微絨毛是同一上皮細胞膜的突起；線粒體在細胞內，微血管及乳糜管在絨毛內，而非微絨毛內。','A one-cell-thick covering provides a short route; it does not mean the entire villus contains only one cell. 單層表示表面只有一層細胞，並非整條絨毛只有一個細胞。','The coloured frame only guides attention. Use the individual adaptation tabs for the actual comparisons and material movement. 彩框只引導觀察；各分頁才展示適應的比較及物質運輸。']],
 long:[['Same start 相同起點','Same speed 同速','Short section ends 短段先完成','More contact time 接觸較久'],['The comparison has the same tube diameter and marker speed; only length differs. 兩管直徑、標記速度相同，只改變長度。','Gold hexagons represent a parcel of digested nutrients moving along the lumen, not through the wall. 金色六角代表在腸腔內前進的已消化營養素，並非穿過腸壁。','The parcel leaves the short section first, so contact with that section has ended. 食糜先離開短段，與該段內壁的接觸已結束。','The longer section has more wall area and the parcel stays beside it longer at the same transit speed. The time units are illustrative. 較長段有更多內壁面積；同速下接觸更久，時間單位只作示意。']],
 folds:[['Same wall span 同一跨度','More exposed surface 暴露面更多','More entry sites 更多入口','More simultaneous uptake 可同時吸收更多'],['Compare a smooth hypothetical lining with a projecting lining over the same horizontal span. Tissue does not grow during the animation. 比較同一水平跨度的假設平滑內壁及突出內壁；組織沒有在動畫中生長。','The green contour is exposed epithelium. Projections add surface within the same wall span. 綠線為暴露上皮，突起在相同跨度內增加表面。','More surface can contain more transport proteins. Green marks are transport sites, not nutrients or energy. 更多表面可容納更多運輸蛋白；綠色位置並非營養素或能量。','Selected nutrient markers cross at several sites at once. Counts illustrate the benefit; they are not a fixed physiological rate ratio. 選定營養素可在多個位置同時進入；數量只說明好處，並非固定生理速率比例。']],
 microvilli:[['ONE cell 一個細胞','Membrane projections 膜突起','More proteins 更多運輸蛋白','More absorption surface 吸收面更多'],['Both panels represent ONE epithelial cell. The smooth comparison isolates the effect of the brush border. 兩圖均代表一個上皮細胞；平滑對照只比較刷狀緣的作用。','Microvilli project into the lumen and are continuous with the apical cell membrane. They are not extra cells or blood vessels. 微絨毛伸向腸腔，與頂端細胞膜相連；並非額外細胞或血管。','More membrane provides more locations for membrane transport proteins. The ATP mechanism is shown separately in Mitochondria. 更多細胞膜提供更多運輸蛋白位置；ATP 機制另見線粒體分頁。','More selected nutrient markers can cross together. This isolates surface area; it does not claim microvilli alone supply energy. 更多選定標記可同時穿過；此圖只比較面積，並非表示微絨毛提供能量。']],
 wall:[['Same sample 同一批標記','Random movement 隨機移動','Shorter route 較短路徑','Earlier arrival 較早到達'],['Purple F markers are fructose, a diffusion example that uses membrane transport proteins. Both sides start with the same twelve markers. 紫色 F 表示果糖，為經運輸蛋白擴散的例子；兩邊均起始十二個標記。','Markers make random forward and backward steps. Diffusion is not a row of molecules travelling at a fixed forward speed. 標記隨機前進及後退，並非分子列隊以固定速度單向前進。','The real intestinal covering is one cell thick. Three layers are a hypothetical comparison, not another normal villus structure. 真正小腸上皮為單層；三層只是假設對照，並非另一種正常絨毛。','With the same random-step model and elapsed time, the shorter path lets more selected markers reach blood. Blood carries arriving markers away; the counter records cumulative arrivals. This is a qualitative distance comparison, not measured permeability data. 相同模型及時間下，較短路徑讓更多標記到達血液；血液繼續帶走，計數為累計到達數。這是定性距離比較，並非實測透性數據。']],
 energy:[['Respiration 呼吸作用','ATP to pump ATP 到泵','Maintain Na⁺ gradient 維持鈉梯度','Nutrient uptake 吸收營養素'],['Many mitochondria supply ATP by aerobic respiration, using fuel and oxygen available to the cell. This view isolates how ATP supports uptake. Blue symbols are ATP; gold hexagons are glucose. 大量線粒體利用細胞內可用的燃料及氧進行有氧呼吸，供 ATP；此圖只突出 ATP 如何支持吸收，藍色為 ATP，金六角為葡萄糖。','ATP transfers energy to the basolateral sodium pump, helping move Na⁺ out of the cell. The apical glucose transporter is not directly fuelled by an ATP particle. ATP 把能量供給基底側鈉泵，協助泵出 Na⁺；頂端葡萄糖運輸蛋白並非直接吞入 ATP。','Keeping intracellular Na⁺ low supports Na⁺ entry from the lumen together with glucose. K⁺ return and ATP recycling are omitted from this focused diagram. 細胞內 Na⁺ 維持較低，使 Na⁺ 可與葡萄糖由腸腔共同進入；此圖省略 K⁺ 回流及 ATP 再生。','Glucose leaves through a separate basal transport protein, crosses tissue fluid and reaches blood. Many mitochondria support the energy demand for this active uptake. 葡萄糖經另一基底側運輸蛋白離開，再經組織液入血；大量線粒體支持主動吸收的能量需求。']],
 blood:[['Same start 相同起點','Solute enters 溶質進入','Remove or accumulate 帶走或積聚','Gradient maintained 維持梯度'],['Both sides start with sixteen selected fructose markers in the lumen and no selected marker in blood. Blood volume is the same. 兩側起初腸腔各有十六個果糖標記，血液均沒有選定標記，血量相同。','Fructose crosses epithelial transport proteins and a nearby capillary wall. Blood cells stay in their vessel. 果糖經上皮運輸蛋白及附近微血管壁進入血液；血球留在血管內。','Flow carries absorbed fructose away. In the no-removal comparison, solute accumulates in blood and the lumen-to-blood difference shrinks. 血流帶走已吸收果糖；沒有帶走時，血中積聚使兩邊濃度差縮小。','Removal maintains a gradient for continued diffusion. Counts refer to equal reference volumes, not the drawn sizes of the compartments; they illustrate the mechanism, not measured rates. 帶走溶質維持擴散梯度；數量比較相同參考體積，而非圖中的區域大小，只示範機制，並非實測速率。']],
 lacteal:[['Enter cell 進細胞','Reassemble 重組','Package and release 包裝及釋出','Drain in lymph 由淋巴帶走'],['Most long-chain dietary lipid is processed inside enterocytes. This route shows monoglycerides (a glycerol backbone with one fatty-acid chain attached) plus free fatty acids. The original school simplification remains in the text. 大部分長鏈膳食脂肪在上皮細胞內處理；此圖展示單甘油酯（一個甘油骨架連一條脂肪酸）及游離脂肪酸，原筆記的簡化模型仍保留在文字內。','Each monoglyceride gains two fatty-acid chains to form a triglyceride: three chains on one backbone. The twelve chains and four backbones stay accounted for. 每個單甘油酯再結合兩條脂肪酸成為甘油三酯，即一個骨架連三條鏈；合共十二條鏈及四個骨架。','Triglycerides are packaged; the outer release vesicle fuses with the cell membrane. This is cellular release, not a whole droplet diffusing through an intact membrane. 甘油三酯包裝後，由釋出囊泡與細胞膜融合；並非整滴油穿過完整細胞膜擴散。','The package enters lacteal flaps and travels away in lymph. A lacteal is a lymphatic capillary; it does not drain directly into the hepatic portal vein. 微粒經活瓣入乳糜管並隨淋巴流走；乳糜管為淋巴微管，並非直接接入肝門靜脈。']],
 mixing:[['Same villus 相同絨毛','Local depletion 表面附近耗減','Renew contents 更新腸液','Maintain difference 維持濃度差'],['Both panels have the same villus and blood removal. Purple F markers represent fructose; this is a diffusion example. 兩圖的絨毛及血流相同，紫色 F 為果糖，示範擴散。','Uptake reduces solute concentration in fluid immediately beside the epithelium. Absorption does not make all intestinal contents nutrient-free. 吸收令緊貼上皮的腸液溶質濃度降低，並非整個腸腔的營養素都消失。','Peristaltic mixing and small villus movements renew contact with freshly digested material. The movement shown is exaggerated; vessels move with tissue. 蠕動攪拌及絨毛小幅運動，使表面接觸新消化物；動作經放大，管道隨組織一同移動。','Renewal sustains the concentration difference near the surface. The less-mixed comparison still has some uptake; mixing is not an on/off switch for absorption. 更新維持表面附近濃度差；較少攪拌時仍有部分吸收，並非開關式效果。']],
 absorption:[['Identify material 辨認物質','Cross one layer 穿單層上皮','Enter the vessel 進管道','Carry away 帶走'],['This is an expanded route diagram, not a literal map of capillary and lacteal positions. See Villus + cell for their arrangement in one villus. 此為放大的路徑圖，並非微血管與乳糜管的位置比例圖；實際排列見絨毛及細胞。','Glucose and amino acids require membrane transport proteins. Water and other dissolved materials have their own mechanisms; the drawing does not imply every nutrient uses the same transporter. 葡萄糖及氨基酸需運輸蛋白；水及其他溶質有各自機制，並非全部共用一種載體。','Blood-soluble materials enter nearby capillaries. Most long-chain dietary fat is processed and packaged within epithelial cells, then enters lymph with fat-soluble vitamins. 水溶性物質入附近微血管；大部分長鏈膳食脂肪在上皮細胞內處理及包裝，再與脂溶性維生素進淋巴。','Markers follow the drawn outflow and fade only as they leave this view; carried-away counts record that exit. No molecule teleports back into the lumen. 標記沿管道流出視圖才淡出，已帶走數記錄其離開，並無分子跳回腸腔。']]
};
stories.villi=[['Same span 同一跨度','Villi project 絨毛突起','More epithelium 更多上皮','More entry sites 更多入口'],['These are villi projecting from the mucosa, enlarged relative to whole-wall folds. The smooth side is hypothetical. 此處放大黏膜上的絨毛，比整個腸壁摺疊小一個尺度；平滑側為假設對照。','Each villus is multicellular and covered by one epithelial layer. It is not a single cell or a microvillus. 每條絨毛含多個細胞，表面覆蓋單層上皮；並非一個細胞或一條微絨毛。','Repeated projections provide more exposed epithelial area in the same wall span. 多個突起在同一腸壁跨度內提供更多上皮面積。','More selected nutrients can enter at multiple sites. The full blood and lymph routes are shown in Absorption. 多個入口可讓更多選定營養素同時進入；完整血液及淋巴路徑見吸收分頁。']];
 stories.folds[1][0]='Circular folds are ridges of the intestinal wall, larger than villi. This section omits the microscopic villi on them so the fold itself is clear. 環形摺疊是比絨毛大的腸壁皺褶；此切面省略其上的微小絨毛，以突出摺疊本身。';
 stories.overview[0]=['Microvilli 微絨毛','Mitochondria 線粒體','Thin layer 單層上皮','Vessels 管道'];
 stories.overview[1][0]='Microvilli are projections of ONE cell membrane and increase its exposed area. Dashed lines link the whole villus to the enlarged epithelial cell. 微絨毛是同一細胞膜的突起，增加暴露面積；虛線連接整條絨毛及放大的上皮細胞。';
 stories.overview[1][1]='Many mitochondria inside epithelial cells supply ATP through respiration to support active nutrient uptake. Capillaries and the lacteal lie inside the villus, not inside microvilli. 上皮細胞內大量線粒體經呼吸作用供 ATP，支持主動吸收；微血管及乳糜管在絨毛內，而非微絨毛內。';
 stories.overview[1][3]='Capillary blood carries absorbed water-soluble nutrients away. The central lacteal drains packaged long-chain fat in lymph. Transport prevents local accumulation. 微血管血液帶走已吸收的水溶性營養素；中央乳糜管以淋巴帶走長鏈脂肪微粒，避免在局部積聚。';

stories.energy=[['Find mitochondria 找線粒體','Supply energy 供應能量','Active uptake 主動吸收','Glucose enters 葡萄糖進入'],['The epithelial cell contains many mitochondria. Gold hexagons are glucose; faded ones show the higher concentration inside the cell. 上皮細胞含大量線粒體；金色六角形為葡萄糖，細胞內淡色標記示意較高濃度。','Aerobic respiration releases energy, made available as ATP. The moving blue ATP symbol links mitochondria to the uptake process; it is not a nutrient. 有氧呼吸釋放能量，以 ATP 供細胞使用；藍色 ATP 標記連結線粒體及吸收過程，並非營養素。','Active transport requires energy and can move substances against their concentration gradient. This course-level diagram omits the intermediate molecular steps. 主動運輸需能量，可逆濃度梯度運輸；此課程示意圖省略中間分子步驟。','The selected glucose has entered the cell. More mitochondria support energy supply for active uptake; they do not form extra membrane layers. 選定葡萄糖已進細胞；大量線粒體支持主動吸收的能量供應，並非增加細胞膜層數。']];
stories.lacteal=[['Locate the route 找途徑','Process in cell 細胞內處理','Package and release 包裝釋出','Lymph drainage 淋巴運走'],['The left villus locates the central lacteal. On the right, follow one portion of long-chain fat digestion products into one epithelial cell. 左圖定位中央乳糜管；右圖追蹤一份長鏈脂肪消化產物進入一個上皮細胞。','Triglycerides are re-formed inside the cell. The symbol represents a selected portion, not a single molecule or reaction ratio. 甘油三酯在細胞內重新組合；標記代表選定份量，並非單一分子或反應比例。','The green ring identifies a transport package; cell release happens before entry through a lacteal side flap. 綠圈代表運輸微粒；先由細胞釋出，再經乳糜管側面的入口進入。','The same package drains in lymph. It does not enter a blood capillary or go directly to the hepatic portal vein. 同一微粒隨淋巴流走；並非進血液微血管或直接進入肝門靜脈。']];
for(const id of ['folds','villi','microvilli'])stories[id]=[
 ['Locate contact 找接觸面','Follow the sides 沿側面','Compare footprint 比較佔地','Absorb at sites 多處吸收'],
 ['Blue fluid fills the lumen and spaces beside the projections. The teal boundary is the food-facing surface; peach is tissue. 藍色腸液位於腸腔及突起之間；綠色邊界為接觸食物的表面，桃色為組織。',
 'Follow the highlight around the tips, down the sides and across the exposed lining between projections. These additional sides also contact the contents. The highlight guides attention; it is not a wave of absorption. 沿亮線觀察頂部、側面及突起間的暴露表面；額外的側面亦接觸腸液。亮線只引導觀察，並非吸收波。',
 id==='microvilli'?'This view shows ONE epithelial cell centred; there is no left comparison panel. Brush-border projections increase food-facing membrane within the same cell footprint. 此圖只顯示置中的一個上皮細胞，沒有左側對照；刷狀緣突起在相同細胞佔地內增加接觸食物的膜面積。':'The hypothetical smooth lining has the same wall footprint and magnification. Projections add exposed sides within that footprint. This section illustrates the relationship, not a numerical area ratio. 假設平滑上皮的腸壁佔地及放大率相同；突起在相同佔地內增加暴露側面。此切面說明關係，並非面積比例量度。',
 'More exposed surface provides more lining where uptake can occur. White rings mark representative sites on the projected surface only; complete membrane and vessel routes are in Absorption. 較多暴露表面提供更多可吸收的上皮；白圈只標示突起上的示意位置，完整跨膜及血管路徑見「吸收途徑」。']
];
